let file = """{"version":3,"file":"numberUtil-Dp4m46lk.js","names":[],"sources":["../../src/utils/numberUtil.ts"],"sourcesContent":["import { clamp } from 'es-toolkit/math'\n\n/**\n * Clamp a numeric value to an integer percent in the range [0, 100].\n *\n * @param value Numeric value expected to be a percentage (0-100)\n * @returns Integer percent between 0 and 100\n */\nexport const clampPercentInt = (value?: number): number => {\n  const v = Math.round(value ?? 0)\n  return clamp(v, 0, 100)\n}\n\n/**\n * Format a percentage (0-100) using the provided locale with 0 fraction digits.\n *\n * @param locale BCP-47 locale string\n * @param value0to100 Percent value in [0, 100]\n * @returns Localized percent string, e.g. \"42%\"\n */\nexport const formatPercent0 = (locale: string, value0to100: number): string => {\n  const v = clampPercentInt(value0to100)\n  return new Intl.NumberFormat(locale, {\n    style: 'percent',\n    maximumFractionDigits: 0\n  }).format((v || 0) / 100)\n}\n\n/**\n * Format an amount given in cents as localized currency. Whole amounts drop the\n * fractional part; fractional cents render two decimals so a charge like 66550\n * cents shows as \"$665.50\" instead of being rounded.\n *\n * @param locale BCP-47 locale string\n * @param cents Amount in integer cents\n * @param currency ISO 4217 code, in either case (Stripe sends lowercase)\n * @returns Localized currency string, e.g. \"$665\" or \"$665.50\"\n */\nexport const formatCurrencyCents = (\n  locale: string,\n  cents: number,\n  currency: string\n): string => {\n  const hasFractionalCents = cents % 100 !== 0\n  return new Intl.NumberFormat(locale, {\n    style: 'currency',\n    currency: currency.toUpperCase(),\n    minimumFractionDigits: hasFractionalCents ? 2 : 0,\n    maximumFractionDigits: hasFractionalCents ? 2 : 0\n  }).format(cents / 100)\n}\n\n/**\n * Format a USD amount given in cents as localized currency.\n *\n * @param locale BCP-47 locale string\n * @param cents USD amount in integer cents\n * @returns Localized currency string, e.g. \"$665\" or \"$665.50\"\n */\nexport const formatUsdCents = (locale: string, cents: number): string =>\n  formatCurrencyCents(locale, cents, 'USD')\n"],"mappings":"uFAQA,IAAa,gBAAmB,GAEvB,EADG,KAAK,MAAM,GAAS,CACjB,EAAG,EAAG,GAAG,EAUX,gBAAkB,EAAgB,IAAgC,CAC7E,IAAM,EAAI,gBAAgB,CAAW,EACrC,OAAO,IAAI,KAAK,aAAa,EAAQ,CACnC,MAAO,UACP,sBAAuB,CACzB,CAAC,CAAC,CAAC,QAAQ,GAAK,GAAK,GAAG,CAC1B,EAYa,qBACX,EACA,EACA,IACW,CACX,IAAM,EAAqB,EAAQ,KAAQ,EAC3C,OAAO,IAAI,KAAK,aAAa,EAAQ,CACnC,MAAO,WACP,SAAU,EAAS,YAAY,EAC/B,sBAAuB,EAAqB,EAAI,EAChD,sBAAuB,EAAqB,EAAI,CAClD,CAAC,CAAC,CAAC,OAAO,EAAQ,GAAG,CACvB,EASa,gBAAkB,EAAgB,IAC7C,oBAAoB,EAAQ,EAAO,KAAK"}"""

